{"status":"candidate","chosen_option":"option1","assumptions":["The input contains the stated number of valid interval lines."],"observations":[{"statement":"Intervals that end at the next interval’s start are compatible, so predecessor lookup must include equal end times.","source_ids":["task"]},{"statement":"The empty selection is permitted, so the dynamic program should never return less than zero.","source_ids":["task"]}],"artifact":{"code":"import sys
from bisect import bisect_right


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n = data[0]
    intervals = [
        (data[1 + 3 * i], data[2 + 3 * i], data[3 + 3 * i])
        for i in range(n)
    ]
    intervals.sort(key=lambda interval: interval[1])

    ends = [interval[1] for interval in intervals]
    dp = [0] * (n + 1)
    for i, (start, end, weight) in enumerate(intervals):
        # Count earlier intervals whose end is <= this interval's start.
        compatible_count = bisect_right(ends, start, 0, i)
        dp[i + 1] = max(dp[i], dp[compatible_count] + weight)

    print(dp[n])


if __name__ == "__main__":
    main()
